<?php require_once dirname(__DIR__).'/core/bootstrap.php';require_admin();$title='داشبورد';$subs=(int)$pdo->query('SELECT COUNT(*) FROM subscriptions')->fetchColumn();$active=(int)$pdo->query('SELECT COUNT(*) FROM subscriptions WHERE active=1')->fetchColumn();$nodes=(int)$pdo->query('SELECT COALESCE(SUM(node_count),0) FROM subscriptions WHERE active=1')->fetchColumn();$ads=(int)$pdo->query('SELECT COUNT(*) FROM ads WHERE active=1')->fetchColumn();$totalDevices=(int)$pdo->query('SELECT COUNT(*) FROM devices')->fetchColumn();$onlineDevices=(int)$pdo->query("SELECT COUNT(*) FROM devices WHERE last_seen_at >= (NOW() - INTERVAL 3 MINUTE)")->fetchColumn();$blockedDevices=(int)$pdo->query('SELECT COUNT(*) FROM devices WHERE blocked=1')->fetchColumn();require __DIR__.'/_header.php';?><div class="grid"><div class="card"><span class="muted">Subscriptionها</span><div class="metric"><?=$subs?></div></div><div class="card"><span class="muted">فعال</span><div class="metric"><?=$active?></div></div><div class="card"><span class="muted">نودهای کش‌شده</span><div class="metric"><?=$nodes?></div></div></div><div class="grid" style="margin-top:14px"><div class="card"><span class="muted">کل دستگاه‌ها</span><div class="metric"><?=$totalDevices?></div></div><div class="card"><span class="muted">آنلاین الان</span><div class="metric"><?=$onlineDevices?></div></div><div class="card"><span class="muted">مسدود شده</span><div class="metric"><?=$blockedDevices?></div></div></div><div class="card" style="margin-top:14px"><h3>وضعیت</h3><p>تبلیغات فعال: <b><?=$ads?></b></p><p>Maintenance: <b><?=setting($pdo,'maintenance_mode','0')==='1'?'ON':'OFF'?></b></p><p>Minimum App Version: <b><?=e(setting($pdo,'minimum_app_version','1.0.0'))?></b></p><p><a class="btn secondary" href="<?=e(app_path('/admin/devices.php'))?>">مشاهده لیست دستگاه‌ها →</a></p></div><?php require __DIR__.'/_footer.php';
